#!/bin/sh
# SPDX-License-Identifier: MIT
set -eu

PROJECT_VERSION="0.2.0"
MODULE_VERSION="5.0"
ROOT=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
KERNEL=$(uname -r)
STATE_DIR=/var/lib/px13-powerd
LIB_DIR=/usr/local/lib/px13-powerd
INSTALL_STATE="$STATE_DIR/install-state"
SUCCESS=0

die()
{
    printf 'px13-linux-power: %s\n' "$*" >&2
    exit 1
}

unit_exists()
{
    systemctl list-unit-files "$1" --no-legend 2>/dev/null | grep -q "^$1"
}

restore_ppd()
{
    [ -f "$INSTALL_STATE" ] || return 0
    # This file is generated by this installer and contains only two fixed keys.
    # shellcheck disable=SC1090
    . "$INSTALL_STATE"
    unit_exists power-profiles-daemon.service || return 0
    systemctl unmask power-profiles-daemon.service >/dev/null 2>&1 || true
    case "${PPD_ENABLED:-unknown}" in
        enabled) systemctl enable power-profiles-daemon.service >/dev/null 2>&1 || true ;;
        disabled) systemctl disable power-profiles-daemon.service >/dev/null 2>&1 || true ;;
        masked) systemctl mask power-profiles-daemon.service >/dev/null 2>&1 || true ;;
    esac
    if [ "${PPD_ACTIVE:-inactive}" = active ]; then
        systemctl start power-profiles-daemon.service >/dev/null 2>&1 || true
    fi
}

rollback()
{
    [ "$SUCCESS" -eq 1 ] || restore_ppd
}
trap rollback EXIT HUP INT TERM

[ "$(id -u)" -eq 0 ] || die "run this installer with sudo"

INSTALL_DEPS=0
ENABLE_S0IX=0
for arg in "$@"; do
    case "$arg" in
        --install-deps) INSTALL_DEPS=1 ;;
        --enable-s0ix) ENABLE_S0IX=1 ;;
        *) die "usage: sudo ./install.sh [--install-deps] [--enable-s0ix]" ;;
    esac
done

if [ "$INSTALL_DEPS" -eq 1 ]; then
    command -v pacman >/dev/null 2>&1 || die "--install-deps currently supports Arch Linux only"
    pkgbase=$(cat "/usr/lib/modules/$KERNEL/pkgbase" 2>/dev/null || true)
    [ -n "$pkgbase" ] || die "cannot determine the current kernel package"
    pacman -S --needed base-devel dkms python-dbus python-gobject python-nvidia-ml-py nvidia-utils asusctl \
        "${pkgbase}-headers"
fi

for command in cc dkms make modprobe nvidia-smi python3 systemctl; do
    command -v "$command" >/dev/null 2>&1 ||
        die "missing dependency: $command (see README.md)"
done
[ -d "/lib/modules/$KERNEL/build" ] ||
    die "kernel headers for $KERNEL are missing"
python3 -c 'import dbus, gi, pynvml' >/dev/null 2>&1 ||
    die "Python dbus, gi or pynvml (python-nvidia-ml-py) modules are missing"
# Only systems with a verified model file are supported; this also validates
# any personal profiles in /etc/px13-powerd/profiles.d.
python3 -B "$ROOT/daemon/px13_powerd.py" --check ||
    die "unsupported system or invalid configuration (see above)"
unit_exists asusd.service || die "asusd.service is missing; install and configure asusctl"
unit_exists nvidia-powerd.service ||
    die "nvidia-powerd.service is missing; install an NVIDIA driver with Dynamic Boost"
nvidia-smi --query-gpu=name,power.default_limit,power.max_limit \
    --format=csv,noheader >/dev/null 2>&1 || die "NVIDIA GPU is not available"

# The daemon switches amd-pstate to active mode at startup, but the kernel
# command line decides the mode used before it runs and after it is removed.
case " $(cat /proc/cmdline) " in
    *" amd_pstate=active "*) ;;
    *)
        printf 'px13-linux-power: warning: the kernel command line does not set amd_pstate=active.\n' >&2
        printf 'px13-linux-power: warning: the daemon switches modes at runtime; set amd_pstate=active (replacing guided) to apply it from boot.\n' >&2
        ;;
esac

for unit in auto-cpufreq.service lactd.service tlp.service; do
    if systemctl is-active --quiet "$unit" 2>/dev/null; then
        die "$unit is active and would conflict with the single-owner power policy"
    fi
done

make -C "$ROOT/nvpcf-override" clean all

install -d -m 0755 "$STATE_DIR" "/usr/src/px13-tgp-$MODULE_VERSION"
if [ ! -f "$INSTALL_STATE" ]; then
    ppd_enabled=$(systemctl is-enabled power-profiles-daemon.service 2>/dev/null || true)
    ppd_active=$(systemctl is-active power-profiles-daemon.service 2>/dev/null || true)
    umask 077
    printf 'PPD_ENABLED=%s\nPPD_ACTIVE=%s\n' \
        "${ppd_enabled:-unknown}" "${ppd_active:-inactive}" >"$INSTALL_STATE"
fi
if unit_exists power-profiles-daemon.service; then
    systemctl disable --now power-profiles-daemon.service >/dev/null 2>&1 || true
    systemctl mask power-profiles-daemon.service >/dev/null
fi

install -m 0644 "$ROOT/module/px13_tgp_probe.c" "$ROOT/module/Makefile" \
    "$ROOT/module/dkms.conf" "/usr/src/px13-tgp-$MODULE_VERSION/"

if ! dkms status -m px13-tgp -v "$MODULE_VERSION" 2>/dev/null | grep -q .; then
    dkms add -m px13-tgp -v "$MODULE_VERSION"
fi
for build_dir in /lib/modules/*/build; do
    [ -d "$build_dir" ] || continue
    kernel=${build_dir#/lib/modules/}
    kernel=${kernel%/build}
    if ! dkms status -m px13-tgp -v "$MODULE_VERSION" -k "$kernel" 2>/dev/null |
        grep -q 'installed'; then
        dkms build -m px13-tgp -v "$MODULE_VERSION" -k "$kernel"
        dkms install -m px13-tgp -v "$MODULE_VERSION" -k "$kernel"
    fi
done

# The 0.1 layout installed a single script; replace the whole directory.
rm -rf "$LIB_DIR"
install -d -m 0755 "$LIB_DIR/px13power" "$LIB_DIR/models" /etc/px13-powerd/profiles.d \
    /etc/systemd/system/nvidia-powerd.service.d
install -m 0755 "$ROOT/daemon/px13_powerd.py" "$ROOT/daemon/px13_benchmark.py" "$LIB_DIR/"
install -m 0644 "$ROOT"/daemon/px13power/*.py "$LIB_DIR/px13power/"
install -m 0644 "$ROOT"/daemon/models/*.toml "$LIB_DIR/models/"
install -m 0755 "$ROOT/daemon/px13ctl.py" /usr/local/bin/px13ctl
install -m 0644 "$ROOT/daemon/px13-powerd.service" \
    /etc/systemd/system/px13-powerd.service
rm -f /etc/dbus-1/system.d/org.asuslinux.Px13Power.conf
install -m 0644 "$ROOT/daemon/px13-powerd.conf" \
    /etc/dbus-1/system.d/org.asuslinux.TuningProvider.conf
install -m 0755 "$ROOT/daemon/px13-powerd.sleep" \
    /usr/lib/systemd/system-sleep/px13-powerd
install -m 0644 "$ROOT/daemon/px13-tgp.conf" \
    /etc/modules-load.d/px13-tgp.conf
install -m 0644 "$ROOT/nvpcf-override/libnvpcf_override.so" \
    "$LIB_DIR/libnvpcf_override.so"
install -m 0644 "$ROOT/nvpcf-override/nvidia-powerd-px13.conf" \
    /etc/systemd/system/nvidia-powerd.service.d/px13-nvpcf.conf

install -m 0644 "$ROOT/nvidia/px13-nvidia-rtd3.conf" \
    /etc/modprobe.d/px13-nvidia-rtd3.conf

if [ "$ENABLE_S0IX" -eq 1 ]; then
    install -m 0644 "$ROOT/nvidia/px13-nvidia-s0ix.conf" \
        /etc/modprobe.d/px13-nvidia-s0ix.conf
fi

systemctl stop px13-powerd.service nvidia-powerd.service 2>/dev/null || true
modprobe -r px13_tgp_probe 2>/dev/null || true
modprobe px13_tgp_probe ||
    die "module load failed; inspect Secure Boot/MOK state and journalctl -k"
[ "$(cat /sys/module/px13_tgp_probe/version)" = "$MODULE_VERSION" ] ||
    die "the loaded module is not version $MODULE_VERSION"

systemctl daemon-reload
systemctl reload dbus.service 2>/dev/null || true
systemctl enable nvidia-powerd.service >/dev/null 2>&1 || true
systemctl start nvidia-powerd.service
systemctl start asusd.service
systemctl enable --now px13-powerd.service
systemctl is-active --quiet asusd.service || die "asusd failed to start"
systemctl is-active --quiet nvidia-powerd.service || die "nvidia-powerd failed to start"
systemctl is-active --quiet px13-powerd.service || die "px13-powerd failed to start"

SUCCESS=1
printf 'PX13 Linux Power %s installed. Limits follow the platform profile (Fn+F5).\n' "$PROJECT_VERSION"
printf 'Run: px13ctl state; sudo ./scripts/doctor.sh\n'
printf 'Personal profiles: see examples/profiles.d and /etc/px13-powerd/profiles.d.\n'
if ! grep -q '^DynamicPowerManagement: 2$' /proc/driver/nvidia/params 2>/dev/null; then
    printf 'RTD3 config installed to /etc/modprobe.d/px13-nvidia-rtd3.conf.\n'
    printf 'Regenerate the initramfs (e.g. sudo mkinitcpio -P) and reboot for it to take effect.\n'
fi
if [ "$ENABLE_S0IX" -eq 1 ]; then
    printf 'S0ix support installed to /etc/modprobe.d/px13-nvidia-s0ix.conf.\n'
    printf 'Regenerate the initramfs (e.g. sudo mkinitcpio -P) and reboot for it to take effect.\n'
fi
